    if (xpathCtx == NULL) {
        xmlFreeDoc(doc);
        return NULL;
    }

    // Sanitize inputs to prevent XPath injection
    char* sanitizedUsername = xmlXPathCastStringToString((const xmlChar*)username);
    char* sanitizedPassword = xmlXPathCastStringToString((const xmlChar*)password);

    char xpathExpr[256];
